import React, { useState } from "react";
import { Box, Typography, Button, Grid, Chip } from "@mui/material";
import { useNavigate } from "react-router-dom";
import simulations from "./simulations";
import { ZB_COLORS } from "./theme";

const categoryColors = {
  Fintech: "#ffd600", Agritech: "#4caf50", Healthcare: "#e91e63",
  Energy: "#ff9800", EdTech: "#2196f3", Logistics: "#9c27b0",
  Policy: "#00bcd4", Tourism: "#ff5722", Media: "#3f51b5",
  Entrepreneurship: "#f44336", "Green Energy": "#4caf50", "Public Health": "#e91e63",
};

const categoryMap = {
  fintech: "Fintech", agritech: "Agritech", healthcare: "Healthcare",
  renewable: "Energy", edtech: "EdTech", logistics: "Logistics",
  publicpolicy: "Policy", tourism: "Tourism", media: "Media",
  entrepreneurship: "Entrepreneurship", greenenergy: "Green Energy", publichealth: "Public Health",
};

export default function SimulationsList({ isLoggedIn }) {
  const navigate = useNavigate();
  const [filter, setFilter] = useState("All");

  const categories = ["All", ...Object.values(categoryMap)];
  const filtered = filter === "All" ? simulations : simulations.filter(s => categoryMap[s.id] === filter);

  const handleStart = (simId) => {
    if (!isLoggedIn) navigate("/login");
    else navigate(`/Simulation/${simId}`);
  };

  return (
    <Box sx={{ maxWidth: 1100, mx: "auto", px: { xs: 2, md: 4 }, py: { xs: 4, md: 6 } }}>
      <Typography sx={{ fontSize: "0.72rem", textTransform: "uppercase", letterSpacing: "0.1em", color: ZB_COLORS.gold, fontWeight: 600, mb: 1, fontFamily: "DM Sans" }}>
        Explore
      </Typography>
      <Typography variant="h4" sx={{ color: "#fff", mb: 0.5 }}>All simulations</Typography>
      <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 3 }}>
        Real-world scenarios across {simulations.length} industries. Pick one and get started.
      </Typography>

      {/* Filters */}
      <Box sx={{ display: "flex", flexWrap: "wrap", gap: 1, mb: 4 }}>
        {categories.map(cat => (
          <Chip
            key={cat}
            label={cat}
            onClick={() => setFilter(cat)}
            sx={{
              cursor: "pointer",
              background: filter === cat ? "rgba(255,214,0,0.15)" : "rgba(255,255,255,0.05)",
              border: `0.5px solid ${filter === cat ? ZB_COLORS.gold : ZB_COLORS.border}`,
              color: filter === cat ? ZB_COLORS.gold : "rgba(255,255,255,0.65)",
              fontFamily: "DM Sans",
            }}
          />
        ))}
      </Box>

      <Grid container spacing={2}>
        {filtered.map((sim) => {
          const cat = categoryMap[sim.id] || "Other";
          const catColor = categoryColors[cat] || ZB_COLORS.gold;
          return (
            <Grid item xs={12} sm={6} md={4} key={sim.id}>
              <Box
                sx={{
                  background: ZB_COLORS.cardBg,
                  border: `0.5px solid ${ZB_COLORS.border}`,
                  borderRadius: "12px",
                  p: 2.5,
                  height: "100%",
                  display: "flex",
                  flexDirection: "column",
                  transition: "all 0.2s ease",
                  "&:hover": { background: ZB_COLORS.cardHover, borderColor: "rgba(255,255,255,0.15)", transform: "translateY(-2px)" },
                }}
              >
                <Chip
                  label={cat}
                  size="small"
                  sx={{
                    background: `${catColor}18`,
                    color: catColor,
                    border: `0.5px solid ${catColor}40`,
                    fontFamily: "DM Sans",
                    fontSize: "0.7rem",
                    mb: 1.5,
                    width: "fit-content",
                  }}
                />
                <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: "#fff", fontSize: "0.95rem", mb: 1 }}>
                  {sim.title}
                </Typography>
                <Typography sx={{ fontSize: "0.82rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", lineHeight: 1.55, flexGrow: 1, mb: 2 }}>
                  {sim.description.slice(0, 100)}…
                </Typography>
                <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                  <Typography sx={{ fontSize: "0.75rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>
                    {sim.tasks.length} tasks
                  </Typography>
                  <Button
                    variant="contained"
                    size="small"
                    onClick={() => handleStart(sim.id)}
                    sx={{ fontSize: "0.8rem", px: 2, py: 0.6 }}
                  >
                    Start →
                  </Button>
                </Box>
              </Box>
            </Grid>
          );
        })}
      </Grid>
    </Box>
  );
}
